const SCHEMA_DOCUMENT: &str = include_str!("../../../../runtime-schema/runtime.openrpc.json");

fn schema_document() -> &'static JsonValue {
    use std::sync::OnceLock;
    static DOCUMENT: OnceLock<JsonValue> = OnceLock::new();
    DOCUMENT.get_or_init(|| {
        serde_json::from_str(SCHEMA_DOCUMENT).expect("runtime schema is valid JSON")
    })
}

fn component_schema(name: &str) -> Option<&'static JsonValue> {
    schema_document()
        .get("components")?
        .get("schemas")?
        .get(name)
}

fn method_schema(name: &str, result: bool) -> Option<&'static JsonValue> {
    let method = schema_document()
        .get("methods")?
        .as_array()?
        .iter()
        .find(|method| method.get("name").and_then(JsonValue::as_str) == Some(name))?;
    if result {
        method.get("result")?.get("schema")
    } else {
        method
            .get("params")?
            .as_array()?
            .first()
            .and_then(|param| param.get("schema"))
            .or_else(|| component_schema("EmptyRequest"))
    }
}

fn event_schema(name: &str) -> Option<&'static JsonValue> {
    schema_document()
        .get("x-tendi")?
        .get("events")?
        .as_array()?
        .iter()
        .find(|event| event.get("name").and_then(JsonValue::as_str) == Some(name))
        .and_then(|event| event.get("payload"))
}

fn resolve_schema<'a>(schema: &'a JsonValue, root: &'a JsonValue) -> Result<&'a JsonValue, String> {
    let Some(reference) = schema.get("$ref").and_then(JsonValue::as_str) else {
        return Ok(schema);
    };
    let mut current = root;
    for part in reference
        .strip_prefix("#/")
        .ok_or_else(|| format!("unsupported schema reference {reference}"))?
        .split('/')
    {
        current = current
            .get(part)
            .ok_or_else(|| format!("schema reference not found: {reference}"))?;
    }
    Ok(current)
}

fn value_type(value: &JsonValue) -> &'static str {
    if value.is_null() {
        "null"
    } else if value.is_boolean() {
        "boolean"
    } else if value.is_string() {
        "string"
    } else if value.is_array() {
        "array"
    } else if value.is_object() {
        "object"
    } else if value.as_i64().is_some() || value.as_u64().is_some() {
        "integer"
    } else {
        "number"
    }
}

fn type_matches(value: &JsonValue, type_name: &str) -> bool {
    match type_name {
        "number" => value.is_number(),
        "integer" => value.is_i64() || value.is_u64(),
        other => value_type(value) == other,
    }
}

fn validate_json_schema(
    value: &JsonValue,
    raw_schema: &JsonValue,
    root: &JsonValue,
    path: &str,
) -> Result<(), String> {
    let schema = resolve_schema(raw_schema, root)?;
    if let Some(any_of) = schema
        .get("anyOf")
        .or_else(|| schema.get("oneOf"))
        .and_then(JsonValue::as_array)
    {
        let matches = any_of
            .iter()
            .filter(|candidate| validate_json_schema(value, candidate, root, path).is_ok())
            .count();
        let required_matches = schema.get("oneOf").is_some();
        if (required_matches && matches != 1) || (!required_matches && matches == 0) {
            return Err(format!("{path} does not match the declared schema"));
        }
        return Ok(());
    }
    if let Some(expected) = schema.get("const") {
        if value != expected {
            return Err(format!("{path} must equal {expected}"));
        }
    }
    if let Some(values) = schema.get("enum").and_then(JsonValue::as_array) {
        if !values.iter().any(|expected| expected == value) {
            return Err(format!("{path} has an invalid enum value"));
        }
    }
    if let Some(types) = schema.get("type") {
        let matches = types
            .as_array()
            .map(|values| {
                values
                    .iter()
                    .filter_map(JsonValue::as_str)
                    .any(|expected| type_matches(value, expected))
            })
            .or_else(|| types.as_str().map(|expected| type_matches(value, expected)))
            .unwrap_or(true);
        if !matches {
            return Err(format!(
                "{path} must be {}, got {}",
                types,
                value_type(value)
            ));
        }
    }
    if let Some(minimum) = schema.get("minimum").and_then(JsonValue::as_f64) {
        if value.as_f64().is_none_or(|actual| actual < minimum) {
            return Err(format!("{path} is below minimum {minimum}"));
        }
    }
    if let Some(maximum) = schema.get("maximum").and_then(JsonValue::as_f64) {
        if value.as_f64().is_none_or(|actual| actual > maximum) {
            return Err(format!("{path} exceeds maximum {maximum}"));
        }
    }
    if let Some(min_length) = schema.get("minLength").and_then(JsonValue::as_u64) {
        if value
            .as_str()
            .is_none_or(|actual| actual.chars().count() < min_length as usize)
        {
            return Err(format!("{path} is shorter than {min_length}"));
        }
    }
    if let Some(max_length) = schema.get("maxLength").and_then(JsonValue::as_u64) {
        if value
            .as_str()
            .is_none_or(|actual| actual.chars().count() > max_length as usize)
        {
            return Err(format!("{path} exceeds length {max_length}"));
        }
    }
    if let Some(items) = schema.get("items") {
        if let Some(values) = value.as_array() {
            for (index, item) in values.iter().enumerate() {
                validate_json_schema(item, items, root, &format!("{path}[{index}]"))?;
            }
        }
    }
    if let Some(object) = value.as_object() {
        let properties = schema.get("properties").and_then(JsonValue::as_object);
        if let Some(required) = schema.get("required").and_then(JsonValue::as_array) {
            for field in required.iter().filter_map(JsonValue::as_str) {
                if !object.contains_key(field) {
                    return Err(format!("{path}.{field} is required"));
                }
            }
        }
        for (field, field_schema) in properties
            .into_iter()
            .flat_map(|properties| properties.iter())
        {
            if let Some(field_value) = object.get(field) {
                validate_json_schema(field_value, field_schema, root, &format!("{path}.{field}"))?;
            }
        }
        if schema.get("additionalProperties") == Some(&JsonValue::Bool(false)) {
            for field in object.keys() {
                if !properties.is_some_and(|properties| properties.contains_key(field)) {
                    return Err(format!("{path}.{field} is not allowed"));
                }
            }
        } else if let Some(additional) = schema
            .get("additionalProperties")
            .filter(|value| value.is_object())
        {
            for (field, field_value) in object {
                if !properties.is_some_and(|properties| properties.contains_key(field)) {
                    validate_json_schema(
                        field_value,
                        additional,
                        root,
                        &format!("{path}.{field}"),
                    )?;
                }
            }
        }
    }
    Ok(())
}

fn validate_method_schema(name: &str, result: bool, value: &JsonValue) -> Result<(), String> {
    let schema =
        method_schema(name, result).ok_or_else(|| format!("schema is missing for {name}"))?;
    validate_json_schema(
        value,
        schema,
        schema_document(),
        if result { "$.result" } else { "$.params" },
    )
}
