pub fn command_requires_serialized_write(name: &str, args: &Value) -> bool {
    if name == "analytics_overview" {
        return args
            .get("refreshTranscripts")
            .and_then(Value::as_bool)
            .unwrap_or(false);
    }
    command_metadata(name).is_some_and(|metadata| metadata.serialized_write)
}
pub fn error_code(kind: &str) -> i32 {
    match kind {
        "INVALID_REQUEST" => -32600,
        "METHOD_NOT_FOUND" => -32601,
        "INVALID_PARAMS" => -32602,
        "INVALID_ARGUMENT" => -32602,
        "INTERNAL" => -32603,
        "CORE_ERROR" => -32603,
        "CONFLICT" => -32002,
        "UNAUTHORIZED" => -32003,
        "UNSUPPORTED_TRANSPORT" => -32004,
        "CONTRACT_VIOLATION" => -32005,
        "DAEMON_ERROR" => -32001,
        _ => -32001,
    }
}
